function skyTexture(top,bottom,night=false){const c=document.createElement('canvas');c.width=1024;c.height=512;const cx=c.getContext('2d'),gradient=cx.createLinearGradient(0,0,0,512);gradient.addColorStop(0,top);gradient.addColorStop(1,bottom);cx.fillStyle=gradient;cx.fillRect(0,0,1024,512);if(night){for(let i=0;i<100;i++){let x=random()*1024,y=random()*260;cx.fillStyle=`rgba(240,238,220,${.15+random()*.5})`;cx.fillRect(x,y,random()*1.3+.4,random()*1.3+.4)}}else{for(let i=0;i<9;i++){let x=random()*1200-100,y=180+random()*260;let g=cx.createRadialGradient(x,y,0,x,y,160);g.addColorStop(0,'rgba(237,199,177,.09)');g.addColorStop(1,'rgba(180,148,140,0)');cx.fillStyle=g;cx.fillRect(x-170,y-170,340,340)}}const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;return t}
const skies={day:skyTexture('#849eaa','#d8c8ac'),dusk:skyTexture('#392e3b','#ab7160'),night:skyTexture('#0b1728','#344255',true)};
const presets={day:{bg:0xa1b4ad,fog:0xa1b4ad,hemi:2.1,sun:2.2,sunColor:0xffe3bc,water:0x55777b,glow:0,glass:.3,lamp:2,time:'10:30'},dusk:{bg:0x533d3c,fog:0x604b49,hemi:1.2,sun:1.6,sunColor:0xffbc89,water:0x283c3d,glow:.6,glass:1.7,lamp:40,time:'17:30'},night:{bg:0x111d28,fog:0x1a2831,hemi:.48,sun:.45,sunColor:0x98b6d9,water:0x142a35,glow:.85,glass:2.2,lamp:55,time:'21:30'}};function setTime(name){const p=presets[name];rockMat.color.setScalar(name==='night'?.34:name==='dusk'?.72:1);scene.background=skies[name];scene.fog.color.setHex(p.fog);hemi.intensity=p.hemi;sun.intensity=p.sun;sun.color.setHex(p.sunColor);water.material.uniforms.color.value.setHex(p.water);mat.glass.color.setHex(name==='day'?0xcaa777:0xffc779);mat.glass.emissiveIntensity=p.glass;frontGlass.emissiveIntensity=name==='day'?.08:.28;interiorLight.intensity=name==='day'?3:9;lanternGlow.emissiveIntensity=name==='day'?.15:2;cabinLight.intensity=p.lamp;backLight.intensity=p.lamp*.2;butterflies.forEach(({butterfly})=>butterfly.visible=name!=='night');document.querySelector('#time').textContent=p.time;document.querySelectorAll('[data-time]').forEach(b=>{const selected=b.dataset.time===name;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected))})}document.querySelectorAll('[data-time]').forEach(b=>b.addEventListener('click',()=>setTime(b.dataset.time)));document.querySelector('#fog').onchange=e=>{scene.fog.density=e.target.checked?.012:0;mist.forEach(({m})=>m.visible=e.target.checked)};document.querySelector('#rotate').onchange=e=>controls.autoRotate=e.target.checked;function reset(){camera.position.copy(start);controls.target.copy(target);controls.update()}document.querySelector('#reset').onclick=reset;document.querySelector('#reset2').onclick=reset;
setTime('dusk');const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);let dt=Math.min(clock.getDelta(),.1),t=clock.elapsedTime;waterUniforms.uTime.value=t;butterflies.forEach(({butterfly,wings,phase})=>{butterfly.position.set(-11+Math.cos(t*.25+phase)*3,1.2+Math.sin(t*1.4+phase)*.2,-5+Math.sin(t*.25+phase)*2);butterfly.rotation.y=-t*.25-phase;wings[0].rotation.z=Math.sin(t*11+phase)*.65;wings[1].rotation.z=-Math.sin(t*11+phase)*.65});smoke.forEach((p,i)=>{let q=(t*.12+i/6)%1;p.position.set(-7.6+q*.9+Math.sin(t*.4+i)*.08,4.2+q*2.7,-1.8);p.scale.set(.7+q*1.25,.45+q*.8,1);p.material.opacity=Math.sin(q*Math.PI)*.7});boat.position.y=.2+Math.sin(t*.75)*.035;boat.rotation.z=Math.sin(t*.6)*.018;mist.forEach(({m,x,phase})=>m.position.x=x+Math.sin(t*.05+phase)*2);flies.forEach(({f,y,phase})=>{f.position.y=y+Math.sin(t*.7+phase)*.2;f.scale.setScalar(.7+.3*Math.sin(t*1.5+phase))});controls.update(dt);renderer.render(scene,camera)}animate();addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.fov=camera.aspect<.85?68:42;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);water.getRenderTarget().setSize(Math.min(innerWidth,1600),Math.min(innerHeight,900))});

